() => {
  // Force dark theme
  document.documentElement.classList.add('dark');
  document.documentElement.style.colorScheme = 'dark';

  // sRGB relative luminance per WCAG
  function srgbLuminance(r, g, b) {
    const lin = c => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  }
  function parseRgb(str) {
    const m = str.match(/rgba?\(([^)]+)\)/);
    if (!m) return null;
    const parts = m[1].split(',').map(s => parseFloat(s.trim()));
    return { r: parts[0], g: parts[1], b: parts[2], a: parts[3] ?? 1 };
  }
  function blend(fg, bg) {
    // Alpha over
    return {
      r: fg.r * fg.a + bg.r * (1 - fg.a),
      g: fg.g * fg.a + bg.g * (1 - fg.a),
      b: fg.b * fg.a + bg.b * (1 - fg.a),
    };
  }
  function contrast(fg, bg) {
    const blended = blend(fg, bg);
    const L1 = srgbLuminance(blended.r, blended.g, blended.b);
    const L2 = srgbLuminance(bg.r, bg.g, bg.b);
    const [a, b] = L1 > L2 ? [L1, L2] : [L2, L1];
    return (a + 0.05) / (b + 0.05);
  }

  const bodyBg = parseRgb(getComputedStyle(document.body).backgroundColor);
  const htmlBg = parseRgb(getComputedStyle(document.documentElement).backgroundColor);

  // Sample various meta-asides
  const samples = [];
  const selectors = [
    { name: 'Hero CTA meta', sel: 'p.font-mono', filter: el => el.textContent.includes('email capture') },
    { name: 'Hero Contents label', sel: '#contents-heading' },
    { name: 'Demo 1 (light wrapper) meta', sel: 'p.font-mono', filter: el => el.textContent.includes('86%') },
    { name: 'Demo 2 (dark essay) meta', sel: 'p.font-mono', filter: el => el.textContent.includes("question you didn't") },
    { name: 'Demo 2 Reality label', sel: 'p', filter: el => el.textContent.trim() === 'Reality' },
  ];

  for (const { name, sel, filter } of selectors) {
    const nodes = Array.from(document.querySelectorAll(sel));
    const el = filter ? nodes.find(filter) : nodes[0];
    if (!el) { samples.push({ name, found: false }); continue; }
    const color = getComputedStyle(el).color;
    // Find actual bg by walking parents
    let parent = el;
    let bg = null;
    while (parent && parent !== document.documentElement) {
      const pbg = getComputedStyle(parent).backgroundColor;
      const parsed = parseRgb(pbg);
      if (parsed && parsed.a > 0 && !(parsed.r === 0 && parsed.g === 0 && parsed.b === 0 && parsed.a === 0)) {
        bg = parsed;
        break;
      }
      parent = parent.parentElement;
    }
    if (!bg) bg = bodyBg || { r: 255, g: 255, b: 255, a: 1 };

    const fg = parseRgb(color);
    const c = fg && bg ? contrast(fg, bg).toFixed(2) : 'n/a';
    samples.push({ name, color, bgActual: `rgb(${Math.round(bg.r)},${Math.round(bg.g)},${Math.round(bg.b)})`, contrast: c });
  }

  return {
    bodyBg: bodyBg ? `rgb(${Math.round(bodyBg.r)},${Math.round(bodyBg.g)},${Math.round(bodyBg.b)})` : null,
    htmlBg: htmlBg ? `rgb(${Math.round(htmlBg.r)},${Math.round(htmlBg.g)},${Math.round(htmlBg.b)})` : null,
    samples,
  };
}

