() => {
  document.documentElement.classList.add('dark');
  document.documentElement.style.colorScheme = 'dark';

  // Use canvas pixel sampling for exact rendered colors
  function getPixelColor(el) {
    // Paint a test div with the computed color and read back via getComputedStyle + canvas
    const computed = getComputedStyle(el);
    const color = computed.color;
    // Create a test element
    const test = document.createElement('div');
    test.style.cssText = `position:fixed;left:-9999px;width:1px;height:1px;background-color:${color}`;
    document.body.appendChild(test);
    const bg = getComputedStyle(test).backgroundColor;
    test.remove();
    return bg; // rgb() or rgba()
  }

  function parseAnyColor(str) {
    // Try rgb/rgba
    let m = str.match(/rgba?\(([^)]+)\)/);
    if (m) {
      const parts = m[1].split(',').map(s => parseFloat(s.trim()));
      return { r: parts[0], g: parts[1], b: parts[2], a: parts[3] ?? 1 };
    }
    return null;
  }

  function srgbLuminance(r, g, b) {
    const lin = c => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  }

  function contrast(fgHex, bgHex) {
    const fg = typeof fgHex === 'object' ? fgHex : parseAnyColor(fgHex);
    const bg = typeof bgHex === 'object' ? bgHex : parseAnyColor(bgHex);
    if (!fg || !bg) return null;
    // Alpha-composite fg over bg
    const a = fg.a ?? 1;
    const composed = {
      r: fg.r * a + bg.r * (1 - a),
      g: fg.g * a + bg.g * (1 - a),
      b: fg.b * a + bg.b * (1 - a),
    };
    const L1 = srgbLuminance(composed.r, composed.g, composed.b);
    const L2 = srgbLuminance(bg.r, bg.g, bg.b);
    const [hi, lo] = L1 > L2 ? [L1, L2] : [L2, L1];
    return +((hi + 0.05) / (lo + 0.05)).toFixed(2);
  }

  function findRealBg(el) {
    // Walk up to find first non-transparent bg
    let p = el;
    while (p && p !== document.documentElement) {
      const bg = getComputedStyle(p).backgroundColor;
      const parsed = parseAnyColor(bg);
      if (parsed && parsed.a > 0.01) return parsed;
      p = p.parentElement;
    }
    return parseAnyColor(getComputedStyle(document.documentElement).backgroundColor);
  }

  const samples = [
    { name: 'Hero CTA meta (light variant / dark mode)', sel: 'p.font-mono', pick: el => el.textContent.includes('email capture') },
    { name: 'Demo 2 meta (dark prop / dark mode)', sel: 'p.font-mono', pick: el => el.textContent.includes("question you didn't") },
    { name: 'Demo 1 meta (light wrapper / dark mode)', sel: 'p.font-mono', pick: el => el.textContent.includes('86%') },
    { name: 'Demo 2 Reality label', sel: 'p', pick: el => el.textContent.trim() === 'Reality' && el.closest('[class*="bg-gray-950"]') },
    { name: 'Demo 1 Reality label', sel: 'p', pick: el => el.textContent.trim() === 'Reality' && !el.closest('[class*="bg-gray-950"]') },
    { name: 'FAQ meta aside (first)', sel: 'p.font-mono', pick: el => el.textContent.includes("lesson one") },
  ];

  const results = [];
  for (const s of samples) {
    const nodes = Array.from(document.querySelectorAll(s.sel));
    const el = nodes.find(s.pick);
    if (!el) { results.push({ name: s.name, found: false }); continue; }
    const fg = parseAnyColor(getPixelColor(el));
    const bg = findRealBg(el);
    const ratio = contrast(fg, bg);
    results.push({
      name: s.name,
      fg: fg ? `rgba(${Math.round(fg.r)},${Math.round(fg.g)},${Math.round(fg.b)},${(fg.a ?? 1).toFixed(2)})` : null,
      bg: bg ? `rgb(${Math.round(bg.r)},${Math.round(bg.g)},${Math.round(bg.b)})` : null,
      ratio,
    });
  }
  return results;
}

