() => {
  document.documentElement.classList.add('dark');
  document.documentElement.style.colorScheme = 'dark';

  const canvas = document.createElement('canvas');
  canvas.width = 1; canvas.height = 1;
  const ctx = canvas.getContext('2d');

  function colorToRgba(cssColor) {
    ctx.clearRect(0, 0, 1, 1);
    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.fillRect(0, 0, 1, 1);
    ctx.fillStyle = cssColor;
    ctx.fillRect(0, 0, 1, 1);
    const d = ctx.getImageData(0, 0, 1, 1).data;
    return { r: d[0], g: d[1], b: d[2], a: d[3] / 255 };
  }

  function srgbLum(r, g, b) {
    const lin = c => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  }

  function contrast(fg, bg) {
    const a = fg.a;
    const c = {
      r: fg.r * a + bg.r * (1 - a),
      g: fg.g * a + bg.g * (1 - a),
      b: fg.b * a + bg.b * (1 - a),
    };
    const L1 = srgbLum(c.r, c.g, c.b);
    const L2 = srgbLum(bg.r, bg.g, bg.b);
    const [hi, lo] = L1 > L2 ? [L1, L2] : [L2, L1];
    return +((hi + 0.05) / (lo + 0.05)).toFixed(2);
  }

  function findBg(el) {
    let p = el;
    while (p && p !== document.documentElement) {
      const bg = getComputedStyle(p).backgroundColor;
      const rgba = colorToRgba(bg);
      if (rgba.a > 0.01) return rgba;
      p = p.parentElement;
    }
    return colorToRgba(getComputedStyle(document.documentElement).backgroundColor);
  }

  const samples = [
    { name: 'Hero CTA meta (no dark prop, dark mode)', sel: 'p.font-mono', pick: el => el.textContent.includes('email capture') },
    { name: 'Demo 2 meta (dark prop, dark mode)', sel: 'p.font-mono', pick: el => el.textContent.includes("question you didn't") },
    { name: 'Demo 1 meta (no dark prop, dark mode)', sel: 'p.font-mono', pick: el => el.textContent.includes('86%') },
    { name: 'Demo 2 Reality label', sel: 'p', pick: el => el.textContent.trim() === 'Reality' && el.closest('[class*="bg-gray-950"]') },
    { name: 'Demo 1 Reality label', sel: 'p', pick: el => el.textContent.trim() === 'Reality' && !el.closest('[class*="bg-gray-950"]') },
    { name: 'FAQ meta (first item)', sel: 'p.font-mono', pick: el => el.textContent.includes('lesson one') },
    { name: 'Demo 3 Status Sketch badge text', sel: 'span', pick: el => el.textContent.trim() === 'Sketch' },
    { name: 'Demo 2 Status Essay badge text', sel: 'span', pick: el => el.textContent.trim() === 'Essay' },
  ];

  const results = [];
  for (const s of samples) {
    const nodes = Array.from(document.querySelectorAll(s.sel));
    const el = nodes.find(s.pick);
    if (!el) { results.push({ name: s.name, found: false }); continue; }
    const color = getComputedStyle(el).color;
    const fg = colorToRgba(color);
    const bg = findBg(el);
    results.push({
      name: s.name,
      fg: `rgba(${fg.r},${fg.g},${fg.b},${fg.a.toFixed(2)})`,
      bg: `rgb(${bg.r},${bg.g},${bg.b})`,
      ratio: contrast(fg, bg),
    });
  }
  return results;
}

